sp_widget.css:
/* ==========================================
   ALERTS CONTAINER
========================================== */

.alerts-container{
    display:flex;
    flex-direction:column;
    gap:12px;
}

/* ==========================================
   ALERT CARD
========================================== */

.alert-card{
    display:flex;
    align-items:center;
    gap:14px;

    padding:14px 16px;

    background:#FFFFFF;

    border:1px solid #E5E7EB;

    border-radius:14px;

    transition:.2s;

    cursor:pointer;
}

.alert-card:hover{
    background:#F8FAFC;
    border-color:#CBD5E1;
}

/* ==========================================
   ICON
========================================== */

.alert-icon{
    width:42px;
    height:42px;

    border-radius:12px;

    display:flex;
    align-items:center;
    justify-content:center;

    font-size:18px;

    flex-shrink:0;
}

/* ==========================================
   CONTENT
========================================== */

.alert-content{
    flex:1;
}

.alert-title{
    font-size:14px;
    font-weight:600;
    margin-bottom:2px;
    color:#0F172A;
}

.alert-message{
    font-size:13px;
    color:#64748B;
}

/* ==========================================
   WARNING
========================================== */

.warning-card{
    border-left:4px solid #F59E0B;
}

.warning-card .alert-icon{
    background:#FFFBEB;
    color:#D97706;
}

/* ==========================================
   INFO
========================================== */

.info-card{
    border-left:4px solid #2563EB;
}

.info-card .alert-icon{
    background:#EFF6FF;
    color:#2563EB;
}

/* ==========================================
   SUCCESS
========================================== */

.success-card{
    border-left:4px solid #16A34A;
}

.success-card .alert-icon{
    background:#ECFDF5;
    color:#16A34A;
}

/* ==========================================
   MOBILE
========================================== */

@media(max-width:768px){

    .alert-card{
        padding:12px;
    }

    .alert-icon{
        width:38px;
        height:38px;
        font-size:16px;
    }

    .alert-title{
        font-size:13px;
    }

    .alert-message{
        font-size:12px;
    }
}

sp_widget.script:
(function() {

    data.alerts = [

        {
            type: 'Warning',
            message: '2 patients missed scheduled doses today'
        },

        {
            type: 'Info',
            message: '1 medication refill request awaiting approval'
        },

        {
            type: 'Success',
            message: '15 medication schedules completed successfully'
        },

        {
            type: 'Warning',
            message: 'Upcoming refill required within 3 days'
        }

    ];

})();
